@startuml

class Person {
  + name : string
  + emailAddress : string
}

class Student extends Person {
}

class Tutor extends Person {
  + bankAccount : string
}

class Subject {
  + name : string
}

class TutoringOffer {
  + expertiseLevel : string
  + hourlyPrice : float
}

class Availability {
  + dayOfWeek : string
  + startTime : time
  + endTime : time
}

class TutoringRequest {
  + requestedLevel : string
  + targetDateTime : datetime
}

class TutoringSession {
  + actualDateTime : datetime
  + status : string
}

class Payment {
  + amount : float
  + method : string
}

class Award {
  + month : string
}

Tutor "1" -- "*" TutoringOffer : offers
TutoringOffer -- "1" Subject
Tutor "1" -- "*" Availability : specifies
Student "1" -- "*" TutoringRequest : makes
TutoringRequest -- "1" Tutor : designated to
TutoringRequest -- "1" Subject : for
TutoringRequest "1" -- "0..1" TutoringSession : results in
Tutor "1" -- "*" TutoringSession : conducts
Student "1" -- "*" TutoringSession : attends
TutoringSession "1" -- "0..1" Payment : paid by
Tutor "1" -- "*" Award : receives
Award -- "1" Subject : for

@enduml

